function longestAwesome(s) {
  const firstIndex = new Array(1 << 10).fill(Infinity);
  firstIndex[0] = -1;
  let mask = 0;
  let best = 0;

  for (let i = 0; i < s.length; i++) {
    mask ^= 1 << Number(s[i]);
    best = Math.max(best, i - firstIndex[mask]);
    for (let digit = 0; digit < 10; digit++) {
      best = Math.max(best, i - firstIndex[mask ^ (1 << digit)]);
    }
    firstIndex[mask] = Math.min(firstIndex[mask], i);
  }
  return best;
}

