function longestAwesome(s) {
  // Count digits in every substring and allow at most one odd count.
  let best = 0;
  for (let start = 0; start < s.length; start++) {
    const counts = new Array(10).fill(0);
    for (let end = start; end < s.length; end++) {
      counts[s.charCodeAt(end) - 48]++;
      const odd = counts.filter(c => c % 2 === 1).length;
      if (odd <= 1) best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

