function generate(rand, size) {
  const length = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 20);
  const alphabet = 1 + Math.floor(rand() * 10);
  const offset = Math.floor(rand() * (11 - alphabet));
  let s = '';
  for (let i = 0; i < length; i++) s += String(offset + Math.floor(rand() * alphabet));
  return [s];
}
